#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Complex {
    real: i32,
    imag: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Machine epsilon fixed as 2 according to the problem statement
    let epsilon = 2;

    // Check if every element's imaginary part is "close to zero"
    // i.e., |imag| <= tol * epsilon
    let all_close = arr.iter().all(|c| c.imag.abs() <= tol * epsilon);

    if all_close {
        // Additionally, if elements are already purely real (imag == 0), 
        // output should equal input.
        // So if all imag == 0, just return arr clone.
        let all_zero_imag = arr.iter().all(|c| c.imag == 0);
        if all_zero_imag {
            return arr;
        }

        // Otherwise, return a new Vec where each Complex has imaginary part zero,
        // real part unchanged.
        arr.into_iter()
            .map(|c| Complex { real: c.real, imag: 0 })
            .collect()
    } else {
        // Otherwise, return the input unchanged.
        arr
    }
}